python3 -c "import json, shlex, subprocess, sys
R='.receipts/bot-06-quality-security/greptile-vs-g1-g6-clarity.json'
BASE=sys.argv[1] if len(sys.argv)>1 else 'origin/main'
d=json.load(open(R))
def sh(a):
    r=subprocess.run(a,capture_output=True,text=True)
    if r.returncode!=0: sys.exit(\"audit: '%s' failed rc=%d: %s\" % (' '.join(a),r.returncode,r.stderr.strip().splitlines()[0][:120]))
    return r.stdout
base=sh(['git','merge-base',BASE,'HEAD']).strip()
if not base: sys.exit('audit: merge-base returned no commit')
changed={l.strip() for l in sh(['git','diff','--name-only',base,'HEAD']).splitlines() if l.strip()}
for l in sh(['git','status','--porcelain']).splitlines():
    if not l or l[:2]=='??': continue
    p=l[3:].strip()
    if '->' in p: p=p.split('->')[-1].strip()
    if p: changed.add(p)
def covered(p):
    o=set()
    for c in d['commands']:
        t=c['cmd']
        if t.startswith(p) and '--files' in t and c['exit_code']==0:
            k=shlex.split(t); o|=set(k[k.index('--files')+1:])
    return o
gaps={n:sorted(changed-covered(p)) for n,p in (('G-1','python3 ci/gates/check_ownership.py'),('G-3','python3 ci/gates/check_secrets.py')) if sorted(changed-covered(p))}
mis=[]
for i,c in enumerate(d['commands']):
    t=c['cmd']
    if not t.startswith('python3 ci/gates/'): continue
    r=subprocess.run(shlex.split(t),capture_output=True,text=True)
    if not (r.returncode==c['exit_code'] and c['output_tail'].split(' \u2014 ')[0].strip() in (r.stdout+r.stderr)): mis.append(i)
print({'changed_paths':len(changed),'uncovered':gaps,'rerun_mismatches':mis})
sys.exit(1 if gaps or mis else 0)"
